<?php
/**
 * File with helper for the language switcher modules in different page builders.
 *
 * @package easy-language
 */

namespace easyLanguage\PageBuilder;

// prevent direct access.
defined( 'ABSPATH' ) || exit;

use easyLanguage\EasyLanguage\Switcher;

/**
 * Helper for the language switcher modules in different page builders.
 *
 * All modules use this helper, so the output is always generated by Switcher::get().
 * The settings are identical to the Elementor widget:
 * - show_icons: show the icons of the languages.
 * - hide_actual_language: hide the actual language.
 * - margin: spacing around each link (applied as padding on the links, like in Elementor).
 */
class Switcher_Helper {
	/**
	 * Return the HTML-output of the language switcher.
	 *
	 * @param bool   $show_icons Whether to show the icons.
	 * @param bool   $hide_actual_language Whether to hide the actual language.
	 * @param string $margin Optional spacing around each link as CSS value (e.g. "5px 10px"), used by page builders without own spacing-controls.
	 * @param string $css_class Optional additional CSS class for the wrapper.
	 *
	 * @return string
	 */
	public static function get_output( bool $show_icons, bool $hide_actual_language, string $margin = '', string $css_class = '' ): string {
		// get the switcher.
		$switcher = wp_kses_post(
			Switcher::get_instance()->get(
				array(
					'hide_actual_language' => $hide_actual_language,
					'show_icons'           => $show_icons,
				)
			)
		);

		// return the switcher without wrapper if no margin and no class is set.
		$margin = self::sanitize_spacing( $margin );
		if ( '' === $margin && '' === $css_class ) {
			return $switcher;
		}

		// create the wrapper.
		$id     = wp_unique_id( 'easy-language-switcher-' );
		$output = '<div id="' . esc_attr( $id ) . '" class="' . esc_attr( trim( 'easy-language-switcher-module ' . $css_class ) ) . '">';

		// add the styles for the links.
		if ( '' !== $margin ) {
			$output .= '<style>#' . esc_attr( $id ) . ' a { padding: ' . esc_attr( $margin ) . '; }</style>';
		}

		// add the switcher and return the result.
		return $output . $switcher . '</div>';
	}

	/**
	 * Return a sanitized CSS spacing value (1 to 4 values like "10px", "0 1em 0 1em" or "5%").
	 *
	 * @param string $value The value to sanitize.
	 *
	 * @return string
	 */
	public static function sanitize_spacing( string $value ): string {
		$value = trim( $value );

		// bail if no value is given.
		if ( '' === $value ) {
			return '';
		}

		// split it in its parts.
		$parts = preg_split( '/\s+/', $value );
		if ( ! is_array( $parts ) || count( $parts ) > 4 ) {
			return '';
		}

		// check each part.
		foreach ( $parts as $index => $part ) {
			// use px for numbers without unit.
			if ( preg_match( '/^\d+(\.\d+)?$/', $part ) ) {
				$parts[ $index ] = $part . ( '0' === $part ? '' : 'px' );
				continue;
			}

			// bail if this is not a valid value.
			if ( ! preg_match( '/^\d+(\.\d+)?(px|em|rem|%|vw|vh)$/', $part ) ) {
				return '';
			}
		}

		// return the resulting value.
		return implode( ' ', $parts );
	}

	/**
	 * Return the title of the language switcher module.
	 *
	 * @return string
	 */
	public static function get_title(): string {
		return __( 'Language Switcher', 'easy-language' );
	}

	/**
	 * Return the labels of the settings, identical to the Elementor widget.
	 *
	 * @return array<string,string>
	 */
	public static function get_labels(): array {
		return array(
			'settings'             => __( 'Settings', 'easy-language' ),
			'show_icons'           => __( 'Show icons', 'easy-language' ),
			'hide_actual_language' => __( 'Hide actual language', 'easy-language' ),
			'spacing'              => __( 'Spacing', 'easy-language' ),
			'margin'               => __( 'Margin', 'easy-language' ),
			'margin_description'   => __( 'Spacing around each language link as CSS value, e.g. "5px 10px".', 'easy-language' ),
		);
	}
}
